using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using SkibidiVpn.WinUI.Services;
namespace SkibidiVpn.WinUI.Views;public sealed partial class SettingsPage:Page{private BackendClient? _backend;private string _current="home";public SettingsPage(){InitializeComponent();}protected override void OnNavigatedTo(Microsoft.UI.Xaml.Navigation.NavigationEventArgs e){base.OnNavigatedTo(e);_backend=e.Parameter as BackendClient;_ = Load();}private async Task Load(){try{var s=await _backend!.GetSettingsAsync();_current=s.NetworkMode;NetworkMode.SelectedIndex=_current.Equals("mobile",StringComparison.OrdinalIgnoreCase)?1:0;StatusText.Text=$"Текущий профиль: {_current}. Таймаут источников: {s.FetcherTimeout}. Изменение профиля применяется к settings.yaml; запущенный pipeline необходимо перезапустить.";}catch(Exception ex){StatusText.Text="Не удалось получить настройки: "+ex.Message;}}private async void Save_Click(object sender,RoutedEventArgs e){try{if(NetworkMode.SelectedItem is not ComboBoxItem item||item.Tag is not string mode)return;await _backend!.SetNetworkModeAsync(mode);_current=mode;StatusText.Text=$"Сохранено: {mode}. Новые параметры будут использованы при следующем запуске проверки.";}catch(Exception ex){StatusText.Text="Ошибка сохранения: "+ex.Message;}}}
